export interface VehicleOffering {
  id: string | number;
  name?: string | null;
  slug?: string | null;
  status?: boolean | number | null;
}

const INITIAL_VEHICLE_KEYS = new Set([
  "auto",
  "auto rickshaw",
  "rickshaw",
  "bike",
]);

const normaliseVehicleKey = (value: string | null | undefined): string =>
  value?.trim().toLowerCase().replace(/[-_]+/g, " ") ?? "";

const isEnabled = (status: VehicleOffering["status"]): boolean =>
  status === undefined || status === null || status === true || status === 1;

/**
 * Phase 1 offering rule: only active Auto/Rickshaw and Bike options can be
 * presented to a Dropa2z Rider. The booking API remains the final authority.
 */
export const getInitialVehicleOptions = <T extends VehicleOffering>(
  vehicles: readonly T[] | null | undefined,
): T[] => {
  if (!vehicles) {
    return [];
  }

  return vehicles.filter(vehicle => {
    const slug = normaliseVehicleKey(vehicle.slug);
    const name = normaliseVehicleKey(vehicle.name);

    return (
      isEnabled(vehicle.status) &&
      (INITIAL_VEHICLE_KEYS.has(slug) || INITIAL_VEHICLE_KEYS.has(name))
    );
  });
};
